{
  "reference": "print.jpg — Katsushika Hokusai, 'The Great Wave off Kanagawa' (Kanagawa-oki nami-ura), from the series Thirty-six Views of Mount Fuji, c. 1831, public domain",
  "scene": "scene/index.html — single-file three.js (r170) low-poly reconstruction, everything built in code, no textures, no build step",
  "taken_from_print": {
    "boats": {
      "count": 3,
      "detail": "the print shows three funa (oshiokuri-bune) with crews of nine, each in a trough: one on the left tucked under the great wave, one mid-right below Mount Fuji, and the largest in the foreground. Rebuilt as three low-poly hulls with nine crew each, in the same relative positions."
    },
    "mountain": {
      "name": "Mount Fuji (Fuji-san)",
      "detail": "snow-capped, small on the horizon between the waves, center-right; rebuilt as a flat-shaded cone with a white cap cone."
    },
    "composition": "great breaking wave with claw-like foam dominating the left, a secondary swell on the right, two-tone blue sea, aged-paper beige sky with a faint sun disc, Fuji small in the center distance — all matched in 3D space.",
    "palette": {
      "paper_beige_sky": "#e8d9b5",
      "deep_prussian_blue": "#1c3f5f",
      "prussian_blue_sea": "#2a5a86",
      "pale_blue_crests": "#7fa8c4",
      "foam_off_white": "#f4efe2",
      "boat_tan": "#b0895a",
      "boat_shadow_tan": "#8a6a3f",
      "crew_dark_teal": "#16323f",
      "fuji_gray": "#8a939e",
      "fuji_snow": "#f5f2ea"
    }
  },
  "motion": "sea swell undulation, wave bob, pulsing claw foam, rocking boats, subtle camera drift"
}


