<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Kanagawa-oki Nami-ura — low-poly 3D wallpaper</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Shippori+Mincho:wght@600;800&display=swap" rel="stylesheet">
<style>
  html, body { margin: 0; height: 100%; overflow: hidden; background: #e8d9b5; }
  canvas { display: block; }
  #cartouche {
    position: fixed; top: 18px; left: 18px; z-index: 10; pointer-events: none;
    font-family: 'Shippori Mincho', 'Yu Mincho', serif;
    color: #3c3a33; opacity: 0.82;
    border: 1px solid rgba(60, 58, 51, 0.45);
    padding: 10px 8px 8px;
    background: rgba(232, 217, 181, 0.35);
  }
  #cartouche .jp { writing-mode: vertical-rl; font-size: 20px; letter-spacing: 0.35em; font-weight: 800; }
  #cartouche .en { margin-top: 8px; font-size: 10px; letter-spacing: 0.18em; text-transform: uppercase; }
</style>
</head>
<body>
<div id="cartouche">
  <span class="jp">神奈川沖浪裏</span>
  <div class="en">The Great Wave off Kanagawa</div>
</div>

<script type="module">
import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js';

/* Palette sampled from print.jpg (the print is the reference; nothing is used as a texture).
   Prussian blues on aged-paper beige, off-white foam, tan boats, dark-teal crews, gray Fuji. */
const C = {
  paper:  0xe8d9b5, // aged-paper sky
  deep:   0x1c3f5f, // deep prussian blue (wave troughs / wave body)
  mid:    0x2a5a86, // prussian blue (open sea)
  pale:   0x7fa8c4, // celadon blue (wave crests)
