  boat:   0xb0895a, // boat tan
  boatDk: 0x8a6a3f, // boat shadow tan
  crew:   0x16323f, // crew dark teal
  fuji:   0x8a939e, // Mount Fuji gray body
  snow:   0xf5f2ea, // Mount Fuji snow cap
  sun:    0xf0e4c4, // faint sun disc
  cloud:  0xefe3c6,
};

const scene = new THREE.Scene();
scene.background = new THREE.Color(C.paper);
scene.fog = new THREE.Fog(C.paper, 28, 78);

const camera = new THREE.PerspectiveCamera(45, innerWidth / innerHeight, 0.1, 200);
const camBase = new THREE.Vector3(0, 4.6, 24);
camera.position.copy(camBase);

